644: impl Monitor {
645:     /// `wake` runs on the watcher's threads whenever changes are pending to
646:     /// [`drain`](Self::drain). It may run for every event, so it must only
647:     /// signal (a bounded `try_send`, a condvar notify) and never block.
648:     pub fn start(wake: impl Fn() + Send + Sync + 'static) -> std::io::Result<Self> {
649:         let (commands, requests) = mpsc::sync_channel(1);
650:         let configuration = Arc::new(Mutex::new(Configuration::default()));
651:         let desired_configuration = configuration.clone();
652:         let wake = Arc::new(wake);
653:         let pending = Arc::new(Mutex::new(Pending::default()));
654:         let state = pending.clone();
655:         let thread = thread::Builder::new()
656:             .name("git-watch".into())
657:             .spawn(move || {
658:                 let create_watcher = || {
659:                     let events = state.clone();
660:                     let signal = wake.clone();
661:                     notify::recommended_watcher(move |event: notify::Result<Event>| {
662:                         // Git status itself produces Access traffic. A requested
663:                         // rescan still reaches the normal recovery path.
664:                         if event.as_ref().is_ok_and(access_only) {
665:                             return;
